  "pour_exact_start": {
    "text": "Pont elég víz van a kancsóban. Vigyázz, ne folyjon ki!",
    "file": "audio/voice/pour_exact_start.mp3"
  },
  "pour_exact_empty": {
    "text": "Elfogyott a víz. Kezdjük újra új poharakkal!",
    "file": "audio/voice/pour_exact_empty.mp3"
  },
  "pour_start": {
    "text": "Kínáljuk meg a barátainkat! Válassz poharat, és tartsd nyomva az öntés gombot! A jelzésig tölts, utána engedd el! Ha tovább öntesz, kicsordul a víz.",
    "file": "audio/voice/pour_start.mp3"
  },
  "pour_tilt": {
    "text": "Tartsd kényelmesen a telefont! Döntsd balra a macihoz, jobbra a nyuszihoz! Középen megáll az öntés.",
    "file": "audio/voice/pour_tilt.mp3"
  },
  "pour_centre": {
    "text": "Hozd vissza középre a telefont! Utána tölthetünk a másik pohárba.",
    "file": "audio/voice/pour_centre.mp3"
  },
  "pour_manual": {
    "text": "Lassan önts a jelzésig! Amikor elengedjük a gombot, megáll a víz.",
    "file": "audio/voice/pour_manual.mp3"
  },
  "pour_two": {
    "text": "A macinak kevesebb, a nyuszinak több víz kell. Figyeld a jelzéseket!",
    "file": "audio/voice/pour_two.mp3"
  },
  "pour_two_reverse": {
    "text": "A nyuszinak kevesebb, a macinak több víz kell. Figyeld a jelzéseket!",
    "file": "audio/voice/pour_two_reverse.mp3"
  },
  "pour_bear_done": {
    "text": "A maci pohara elkészült! Köszönöm!",
    "file": "audio/voice/pour_bear_done.mp3"
  },
  "pour_rabbit_done": {
    "text": "A nyuszi pohara elkészült! Köszönöm!",
    "file": "audio/voice/pour_rabbit_done.mp3"
  },
  "pour_more": {
    "text": "Még egy kicsi víz kell. Töltsünk a jelzésig!",
    "file": "audio/voice/pour_more.mp3"
  },
  "pour_over": {
    "text": "Kicsit sok lett. Önts vissza egy keveset a pohárból!",
    "file": "audio/voice/pour_over.mp3"
  },
  "pour_spill": {
    "text": "Hopp, kicsordult a víz! Állítsd meg az öntést, és ürítsd ki a poharat!",
    "file": "audio/voice/pour_spill.mp3"
  },
  "pour_empty": {
    "text": "Elfogyott a víz a kancsóból. A feltöltöm gombbal hozhatunk még vizet!",
    "file": "audio/voice/pour_empty.mp3"
  },
  "pour_refill": {
    "text": "Újra tele a kancsó! Folytathatjuk az öntést.",
    "file": "audio/voice/pour_refill.mp3"
  },
  "pour_done": {
    "text": "Mindkét barátunk kapott inni! Kezdődhet a piknik!",
    "file": "audio/voice/pour_done.mp3"
  },
  "r_post_wishes": {
    "text": "Minden ház mást kér. Mondd a szót, aztán vidd a csomagot ahhoz, aki kérte!",
    "file": "audio/voice/r_post_wishes.mp3"
  },
  "r_hub": {
    "text": "Róka és robot vár rád! Hallgassunk szavakat, mondjunk mondókát, és játsszunk együtt!",
    "file": "audio/voice/r_hub.mp3"
  },
  "r_hunter": {
    "text": "Hallgasd meg a szót! Koppints a képére!",
    "file": "audio/voice/r_hunter.mp3"
  },
  "r_hunter_sound": {
    "text": "Hallgasd meg a képek nevét! Keresd meg azt, amelyikben hallod az R hangot!",
    "file": "audio/voice/r_hunter_sound.mp3"
  },
  "r_hunter_position": {
    "text": "Hallgasd meg a szót! Mutasd meg, hol hallod az R hangot: az elején, a közepén vagy a végén!",
    "file": "audio/voice/r_hunter_position.mp3"
  },
  "r_position_initial": {
    "text": "A szó elején hallod az R hangot.",
    "file": "audio/voice/r_position_initial.mp3"
  },
  "r_position_medial": {
    "text": "A szó közepén hallod az R hangot.",
    "file": "audio/voice/r_position_medial.mp3"
  },
  "r_position_final": {
    "text": "A szó végén hallod az R hangot.",
    "file": "audio/voice/r_position_final.mp3"
  },
  "r_post": {
    "text": "Két összetartozó csomagot kézbesítünk. Mondd a szót, aztán válassz egy házat!",
    "file": "audio/voice/r_post.mp3"
  },
  "r_workshop": {
    "text": "Díszítsük fel a perecműhelyt! Mondd utánam a szót, válassz díszt, és tedd a műhelybe!",
    "file": "audio/voice/r_workshop.mp3"
  },
  "r_rhyme": {
    "text": "Hallgassunk mondókát! Koppints egy sorra, és mondd utánam!",
    "file": "audio/voice/r_rhyme.mp3"
  },
  "r_rhyme_gap": {
    "text": "Elbújt egy szó a mondókából. Hallgasd meg a sort, és keresd meg a hiányzó szó képét!",
    "file": "audio/voice/r_rhyme_gap.mp3"
  },
  "r_echo": {
    "text": "Hallgasd meg a mintát! A mikrofon gombbal felveheted a saját hangodat.",
    "file": "audio/voice/r_echo.mp3"
  },
  "r_try": {
    "text": "Most te jössz!",
    "file": "audio/voice/r_try.mp3"
  },
  "r_compare": {
    "text": "Hallgassuk meg ezt a két szót! Figyeld a világító képet!",
    "file": "audio/voice/r_compare.mp3"
  },
  "r_post_ready": {
    "text": "Kész a csomag! Koppints annak a házára, akinek küldöd!",
    "file": "audio/voice/r_post_ready.mp3"
  },
  "r_decorate_choose": {
    "text": "Válassz egy díszt! Utána koppints egy helyre a műhelyben!",
    "file": "audio/voice/r_decorate_choose.mp3"
  },
  "r_rhyme_repeat": {
    "text": "Most mondjátok ti! Ha készen vagytok, jöhet a következő rész.",
    "file": "audio/voice/r_rhyme_repeat.mp3"
  },
  "r_story": {
    "text": "Tegyük sorba a mondóka képeit! Melyik volt először?",
    "file": "audio/voice/r_story.mp3"
  },
  "r_story_retry": {
    "text": "Nézzük meg újra! Meghallgathatod a képet a hanggombjával.",
    "file": "audio/voice/r_story_retry.mp3"
  },
  "r_story_done": {
    "text": "Sorba rendeztük a mondóka képeit!",
    "file": "audio/voice/r_story_done.mp3"
  },
  "r_echo_compare": {
    "text": "Először a minta, utána a saját hangod szól.",
    "file": "audio/voice/r_echo_compare.mp3"
  },
  "r_echo_yours": {
    "text": "Most a saját hangod következik.",
    "file": "audio/voice/r_echo_yours.mp3"
  },
  "r_retry": {
    "text": "Hallgassuk meg még egyszer! Próbálhatjuk együtt is.",
    "file": "audio/voice/r_retry.mp3"
  },
  "r_found": {
    "text": "Megtaláltad a képet!",
    "file": "audio/voice/r_found.mp3"
  },
  "r_try_thanks": {
    "text": "Köszönöm, hogy próbálkoztál!",
    "file": "audio/voice/r_try_thanks.mp3"
  },
  "r_delivered": {
    "text": "Megérkezett a csomag! Köszönöm a kézbesítést.",
    "file": "audio/voice/r_delivered.mp3"
  },
  "r_decorated": {
    "text": "Új dísz került a műhelybe!",
    "file": "audio/voice/r_decorated.mp3"
  },
  "r_round_done": {
    "text": "Elkészült a közös játék! Jöhet egy újabb kaland.",
    "file": "audio/voice/r_round_done.mp3"
  },
